CREATE TABLE t8
(
  c1 INT,
  c2 DATETIME NOT NULL
)
DUPLICATE KEY(c1)
PARTITION BY RANGE(c2) (
  FROM ('2020-01-01') TO ('2020-01-10') INTERVAL 1 DAY
)
DISTRIBUTED BY RANDOM
PROPERTIES (
  'replication_num' = '1'
);

CREATE TABLE t9
(
  id INT
)
PARTITION BY RANGE(id) (
  PARTITION p1 VALUES (("1"), ("10")),
  PARTITION p2 VALUES (("10"), ("20"))
);

